//! Comprehensive CLI content-correctness matrix.
//!
//! This test file aims to validate every command × every language ×
//! every taint-propagation construct end-to-end. Three layers stack
//! together to produce broad coverage:
//!
//!  1. **Per-language modules** — generated by the `lang_matrix!`
//!     macro. Each language gets its own `mod <lang>` containing the
//!     full set of CLI commands exercised against both the `micro`
//!     and `complex` fixtures (where complex exists and is non-
//!     trivial). One command per test so cargo failure output
//!     points at the exact (lang, command, fixture) cell.
//!
//!  2. **Construct-coverage tests** — every flow-oriented Python
//!     construct that `mega_flow` threads taint through
//!     (decorator factory, async generator, context manager,
//!     match/case, walrus, comprehension, closure, etc.). A dedicated
//!     test per construct drills inspect/security into the specific
//!     hop and asserts taint reaches the sink through it.
//!
//!  3. **Field-shape + edge-case tests** — JSON schema assertions,
//!     flow-id round-trip, stable-id shape checks, severity
//!     validation, nonexistent-workspace handling, pagination
//!     cursor correctness, regex error reporting, compact mode,
//!     DOT output, every `--format` variant.
//!
//! Each test skips gracefully (via the `bin_path()` early return)
//! when the release binary isn't built yet, so `cargo test` before
//! `cargo build --release` still runs cleanly.

use std::path::PathBuf;
use std::process::Command;

fn repo_root() -> PathBuf {
    let mut p = std::env::current_dir().expect("cwd");
    p.push("../..");
    p.canonicalize().expect("repo root")
}

fn bin_path() -> Option<PathBuf> {
    if let Some(path) = option_env!("CARGO_BIN_EXE_bonsai-ninja") {
        return Some(PathBuf::from(path));
    }
    let p = repo_root().join("target/release/bonsai-ninja");
    if p.exists() {
        Some(p)
    } else {
        eprintln!("skipping CLI matrix: release binary missing at {}", p.display());
        None
    }
}

/// Run `bonsai-ninja` with `args` (plus `--no-color --no-progress`)
/// from the repo root so `./security-patterns/` resolves. Returns
/// `None` when the binary isn't built — every `#[test]` exits
/// cleanly in that case. `COLUMNS=240` so tables don't wrap in a
/// way the string-contains checks would miss.
fn run(args: &[&str]) -> Option<(String, String, i32)> {
    let bin = bin_path()?;
    let mut full: Vec<&str> = args.to_vec();
    full.push("--no-color");
    full.push("--no-progress");
    let out = Command::new(&bin)
        .args(&full)
        .env("COLUMNS", "240")
        .current_dir(repo_root())
        .output()
        .expect("spawn bonsai-ninja");
    Some((
        String::from_utf8_lossy(&out.stdout).to_string(),
        {
            let stderr = String::from_utf8_lossy(&out.stderr).to_string();
            assert_success_stderr_is_polished(args, &stderr, out.status.code().unwrap_or(-1));
            stderr
        },
        out.status.code().unwrap_or(-1),
    ))
}

fn assert_success_stderr_is_polished(args: &[&str], stderr: &str, code: i32) {
    if code != 0 {
        return;
    }
    let forbidden = [
        "[security-progress]",
        "[workspace-cache]",
        "[security-phase]",
        "taint-cache:",
        "scope:",
        "cache dataflow",
        "cache callgraph",
        "cache IDG",
        "files=",
        "source_rules=",
        "sink_rules=",
        "sanitizer_rules=",
        "disk_entries=",
        "resident_before=",
        "entries=0",
        "ticks=",
    ];
    for needle in forbidden {
        assert!(
            !stderr.contains(needle),
            "successful CLI matrix command leaked raw/progress stderr `{needle}` for args {args:?}:\n{stderr}"
        );
    }
}

/// Extract the rows array from a JSON response. Browse commands
/// return a bare `[...]` by default; security commands return a
/// `{page, rows}` wrapper. This accepts either shape.
fn rows_of(v: &serde_json::Value) -> Vec<serde_json::Value> {
    if let Some(arr) = v.as_array() {
        return arr.clone();
    }
    if let Some(obj) = v.as_object() {
        if let Some(rows) = obj.get("rows").and_then(|r| r.as_array()) {
            return rows.clone();
        }
    }
    Vec::new()
}

/// Workspace path for a (lang, fixture). Fixture is typically
/// "micro" or "complex".
fn ws(lang: &str, fixture: &str) -> String {
    repo_root()
        .join("examples")
        .join(lang)
        .join(fixture)
        .to_string_lossy()
        .into_owned()
}

/// One language's expected-content signals. Names are substrings —
/// matched against JSON field content or stdout text — so mixed-case
/// conventions across the 21 languages all line up.
#[derive(Copy, Clone)]
pub struct LangExp {
    pub lang: &'static str,
    /// Handler names in the `micro` fixture. All five must appear as
    /// decls in `defs` output.
    pub verify_token: &'static str,
    pub get_user: &'static str,
    pub handle_request: &'static str,
    pub run_admin_command: &'static str,
    pub update_user: &'static str,
    /// A substring that must appear in the command-injection sink
    /// call site (e.g. `os.system`, `Runtime.getRuntime`,
    /// `System.cmd`, `exec.Command`).
    pub cmdi_sink: &'static str,
    /// A substring that must appear in the SQL-injection sink site.
    pub sqli_sink: &'static str,
    /// Minimum expected `security taint-analysis` findings on the micro
    /// fixture.
    pub min_findings_micro: usize,
    /// Minimum expected `security taint-analysis` findings on the complex
    /// fixture. Big codebases should produce many — this asserts the
    /// analyzer didn't silently regress on a large workload.
    pub min_findings_complex: usize,
    /// Minimum decl count in `complex`. Catches adapter regressions
    /// that drop broad swaths of the declaration set.
    pub min_complex_decls: usize,
    /// Whether the adapter populates the `refs` index with named
    /// function references (Erlang / Obj-C model cross-module calls
    /// through flow_events instead of refs, so skip `refs` checks
    /// there).
    pub refs_populated: bool,
    /// Whether the fixture declares at least one class-kind decl.
    /// Non-class languages (C, procedural) stay off this list.
    pub has_classes: bool,
    /// Minimum expected source matches in `security sources` on the
    /// micro fixture. Zero is meaningful: some language micro fixtures
    /// intentionally exercise local-only APIs without a modelled
    /// remote source.
    pub min_sources_micro: usize,
    /// Minimum expected downstream source-flow rows in `security
    /// source-analysis` on the micro fixture.
    pub min_source_flows_micro: usize,
    /// Minimum package/dependency inventory rows for `security deps`.
    pub min_deps_micro: usize,
    /// Minimum sanitizer inventory rows for `security sanitizers`.
    pub min_sanitizers_micro: usize,
}

