// =============================================================================
// Shared check helpers
// =============================================================================

/// Assert that every given `needle` appears as a decl `name` in the
/// JSON output of `defs <ws>`.
fn check_defs_contains(ws: &str, lang: &str, needles: &[&str]) {
    let Some((out, _, code)) = run(&["defs", ws, "--format", "json"]) else {
        return;
    };
    assert_eq!(code, 0, "[{lang}] defs ec={code}");
    let parsed: serde_json::Value = serde_json::from_str(&out).unwrap();
    let rows = rows_of(&parsed);
    let names: Vec<String> = rows
        .iter()
        .filter_map(|r| r.get("name").and_then(|n| n.as_str()).map(String::from))
        .collect();
    for needle in needles {
        assert!(
            names.iter().any(|n| n == needle),
            "[{lang}] defs missing `{needle}`; got {} names",
            names.len()
        );
    }
    // Every row must carry the minimum required fields.
    for row in &rows {
        for field in ["name", "kind", "file", "line", "column"] {
            assert!(
                row.get(field).is_some(),
                "[{lang}] defs row missing `{field}`: {row}"
            );
        }
    }
}

/// Assert `defs --kind function` restricts to function-kind decls
/// and still returns at least one row for every non-trivial fixture.
fn check_defs_kind_filter(ws: &str, lang: &str) {
    let Some((out, _, code)) = run(&["defs", ws, "--kind", "function", "--format", "json"]) else {
        return;
    };
    assert_eq!(code, 0, "[{lang}] defs --kind function ec={code}");
    let parsed: serde_json::Value = serde_json::from_str(&out).unwrap();
    let rows = rows_of(&parsed);
    // Every row must have kind == "function" (substring-match
    // semantics — "function" matches "function" but not "class").
    for row in &rows {
        let kind = row.get("kind").and_then(|k| k.as_str()).unwrap_or("");
        assert!(
            kind.contains("function"),
            "[{lang}] defs --kind function leaked a non-function row: {row}"
        );
    }
}

/// Assert `calls` JSON carries the expected fields and includes at
/// least one call site whose callee mentions the given needle.
fn check_calls_include(ws: &str, lang: &str, callee_needle: &str) {
    let Some((out, _, code)) = run(&["calls", ws, "--format", "json"]) else {
        return;
    };
    assert_eq!(code, 0, "[{lang}] calls ec={code}");
    let parsed: serde_json::Value = serde_json::from_str(&out).unwrap();
    let rows = rows_of(&parsed);
    assert!(!rows.is_empty(), "[{lang}] calls empty");
    let callees: Vec<String> = rows
        .iter()
        .filter_map(|r| r.get("callee").and_then(|c| c.as_str()).map(String::from))
        .collect();
    assert!(
        callees.iter().any(|c| c.contains(callee_needle)),
        "[{lang}] calls missing callee matching `{callee_needle}`; got {} callees",
        callees.len()
    );
    for row in &rows {
        for field in ["resolution_scope", "callee", "file", "line"] {
            assert!(
                row.get(field).is_some(),
                "[{lang}] calls row missing `{field}`: {row}"
            );
        }
        assert_eq!(
            row.get("resolution_scope").and_then(|scope| scope.as_str()),
            Some("syntactic-call-site"),
            "[{lang}] calls row must declare that it is call-site inventory, not a resolved callgraph edge: {row}"
        );
    }
}

