/// Assert `inspect --flow F:id` round-trips correctly for a flow
/// surfaced from the initial query.
fn check_flow_id_roundtrip(ws: &str, lang: &str, query: &str) {
    let Some((out, _, _)) = run(&[
        "inspect",
        ws,
        "--query",
        query,
        "--graph-flow",
        "--format",
        "json",
    ]) else {
        return;
    };
    let parsed: serde_json::Value = match serde_json::from_str(&out) {
        Ok(v) => v,
        Err(_) => return,
    };
    // Find a flow id anywhere in decl_hits.
    let mut flow_id: Option<String> = None;
    if let Some(hits) = parsed.get("decl_hits").and_then(|h| h.as_array()) {
        'outer: for hit in hits {
            if let Some(flows) = hit.get("flows").and_then(|f| f.as_array()) {
                for f in flows {
                    if let Some(id) = f.get("flow_id").and_then(|x| x.as_str()) {
                        if id.starts_with("F:") && id.len() == 18 {
                            flow_id = Some(id.to_string());
                            break 'outer;
                        }
                    }
                }
            }
        }
    }
    let Some(fid) = flow_id else { return };
    let Some((round, _, code)) = run(&["inspect", ws, "--query", query, "--graph-flow", "--flow", &fid])
    else {
        return;
    };
    assert_eq!(code, 0, "[{lang}] --flow {fid} ec={code}");
    assert!(round.contains(&fid), "[{lang}] --flow {fid} didn't echo id");
}

