/// Assert `export`'s `taint_graph` has every expected section and
/// every FuncId reference resolves to a function in the map.
fn check_export_taint_graph(ws: &str, lang: &str, min_functions: usize, expected_fn: &str) {
    let Some((out, _, code)) = run(&["export", ws]) else {
        return;
    };
    assert_eq!(code, 0, "[{lang}] export ec={code}");
    let parsed: serde_json::Value = serde_json::from_str(&out).unwrap();
    let tg = parsed
        .get("taint_graph")
        .unwrap_or_else(|| panic!("[{lang}] export missing taint_graph"));
    for section in [
        "functions",
        "call_edges",
        "function_summaries",
        "reachable_facts",
        "assign_chains",
        "intra_taint",
        "alias_maps",
        "class_fields",
        "entry_points",
        "propagations",
        "chains",
        "flow_id_labels",
    ] {
        assert!(
            tg.get(section).is_some(),
            "[{lang}] export.taint_graph missing `{section}`"
        );
    }
    let fns = tg["functions"].as_array().unwrap();
    assert!(
        fns.len() >= min_functions,
        "[{lang}] export functions={}, want >= {min_functions}",
        fns.len()
    );
    let names: Vec<&str> = fns
        .iter()
        .filter_map(|f| f.get("name").and_then(|n| n.as_str()))
        .collect();
    assert!(
        names.contains(&expected_fn),
        "[{lang}] export.functions missing `{expected_fn}`"
    );
    // FuncId integrity: every call_edge's `from` / `to` must resolve
    // to a function in the map.
    let ids: std::collections::HashSet<u64> = fns
        .iter()
        .filter_map(|f| f.get("func_id").and_then(|v| v.as_u64()))
        .collect();
    for edge in tg["call_edges"].as_array().unwrap() {
        let from = edge.get("from").and_then(|v| v.as_u64()).unwrap_or(u64::MAX);
        let to = edge.get("to").and_then(|v| v.as_u64()).unwrap_or(u64::MAX);
        assert!(
            ids.contains(&from),
            "[{lang}] call_edge.from={from} not in functions map"
        );
        assert!(
            ids.contains(&to),
            "[{lang}] call_edge.to={to} not in functions map"
        );
    }
}

