/// Assert `security taint-analysis` produces at least `min` findings with
/// valid stable ids.
fn check_security_flows(ws: &str, lang: &str, min: usize) {
    // Inferred entry-point sources are opt-in at the CLI by default
    // (per commit 1f4922c). The min-finding expectations were authored
    // against the inferred-on surface; opt in here for test stability,
    // matching what scripts/validate-mega-cli.py does.
    let Some((out, _, code)) = run(&[
        "security",
        ws,
        "taint-analysis",
        "--inferred-sources",
        "--all",
        "--format",
        "json",
    ]) else {
        return;
    };
    assert_eq!(code, 0, "[{lang}] security taint-analysis ec={code}");
    let parsed: serde_json::Value = serde_json::from_str(&out).unwrap();
    assert_eq!(
        parsed.get("analysis_complete").and_then(|value| value.as_bool()),
        Some(true),
        "[{lang}] security taint-analysis incomplete: {:?}",
        parsed.get("incomplete_reasons")
    );
    let rows = rows_of(&parsed);
    assert!(
        rows.len() >= min,
        "[{lang}] security taint-analysis = {}, want >= {min}",
        rows.len()
    );
    for r in &rows {
        let id = r.get("finding_id").and_then(|v| v.as_str()).unwrap_or("");
        assert!(
            id.starts_with("S:") && id.len() == 18,
            "[{lang}] finding_id malformed: {id}"
        );
        let sink_rule = r
            .get("sink")
            .and_then(|s| s.get("rule_id"))
            .and_then(|s| s.as_str())
            .unwrap_or("");
        assert!(
            !sink_rule.is_empty(),
            "[{lang}] finding missing sink.rule_id: {r}"
        );
        // Every finding must have a non-empty source too.
        let src_rule = r
            .get("source")
            .and_then(|s| s.get("rule_id"))
            .and_then(|s| s.as_str())
            .unwrap_or("");
        assert!(!src_rule.is_empty(), "[{lang}] finding missing source");
    }
}

fn expected_default_mega_flow_findings(lang: &str) -> usize {
    // Counts for the DEFAULT `taint-analysis --all` run — concrete
    // source-rule matches only, NO `--inferred-sources`. So a language
    // whose mega_flow source is an inferred entry-point parameter (rather
    // than a concrete rule match) legitimately reports 0 here while
    // `--inferred-sources` shows its real flow (see the parallel
    // `expected_mega_flow_findings_with_inferred_sources` in
    // security_pipeline_regressions.rs). The cpp/csharp/dart/elixir/java/
    // scala/swift entries went 0→1 when d332009 closed the FN-language
    // construct gaps; objc went 2→1 when the xxe over-claim was removed;
    // solidity went 1→0 once its concrete-source FP was dropped (its real
    // flow seeds from an inferred entry param); dart settled at 1 after
    // the combiner's group_id dedup collapsed a duplicate entry-chain row.
    match lang {
        "c" => 1,
        "cpp" => 1,
        "csharp" => 1,
        "dart" => 1,
        "elixir" => 1,
        // io:get_line is a concrete CLI source and reaches os:cmd through
        // the full mega-flow chain.
        "erlang" => 1,
        "go" => 1,
        "java" => 1,
        "javascript" => 1,
        "kotlin" => 1,
        // The old count included LuaSQL-shaped SQLi false positives on
        // generic executor calls without LuaSQL package evidence. The
        // default mega-flow fixture now has one real command-injection flow.
        "lua" => 1,
        // One real command-injection (stdin_fgets → system). The earlier
        // count of 2 included an xxe over-claim that was removed.
        "objc" => 1,
        "perl" => 2,
        // Two real vulns: readline → shell_exec (CWE-78) and
        // superglobal_server → echo (CWE-79).
        "php" => 2,
        "python" => 1,
        // One distinct stdin_gets -> Kernel.system vulnerability. Older
        // baselines counted an equivalent receiver-derived chain twice.
        "ruby" => 1,
        // stdin.lock().read_line is a concrete CLI source and reaches the
        // command argument sink through the full mega-flow chain.
        "rust" => 1,
        "scala" => 1,
        // One concrete information-exposure finding from `msg.sender`
        // in the audit modifier. The reentrancy chain through
        // `handle -> orchestrate -> persist` still needs
        // `--inferred-sources` because its payload starts at an entry
        // parameter.
        "solidity" => 1,
        "swift" => 1,
        "typescript" => 1,
        other => panic!("missing mega_flow expected finding count for {other}"),
    }
}

/// Assert `security taint-analysis --format sarif` produces a
/// well-formed SARIF 2.1.0 document. Required surface (per
/// docs/security-spec.mdx and the SARIF spec):
/// - `version` == `2.1.0`
/// - `$schema` references the SARIF 2.1.0 schema URI
/// - `runs[0].tool.driver.name` == `bonsai-ninja`
/// - `runs[0].results` is an array (may be empty for langs whose
///   micro fixture produces no findings; assert structure either way)
/// - every result has `ruleId`, `level`, `message.text`, `locations[0]`
/// - every result's `properties.bonsai.finding_id` matches the `S:`
///   id from JSON output with the same source-independent pattern-only
///   surface SARIF includes for code-scanning consumers
fn check_security_sarif_shape(ws: &str, lang: &str) {
    let Some((sarif_out, _, sarif_code)) = run(&[
        "security",
        ws,
        "taint-analysis",
        "--inferred-sources",
        "--format",
        "sarif",
    ]) else {
        return;
    };
    assert_eq!(
        sarif_code, 0,
        "[{lang}] security taint-analysis sarif ec={sarif_code}"
    );
    let sarif: serde_json::Value =
        serde_json::from_str(&sarif_out).unwrap_or_else(|e| panic!("[{lang}] sarif parse: {e}"));
    assert_eq!(sarif["version"], "2.1.0", "[{lang}] sarif version mismatch");
    assert!(
        sarif["$schema"]
            .as_str()
            .unwrap_or("")
            .contains("sarif-schema-2.1.0"),
        "[{lang}] sarif $schema missing or wrong"
    );
    assert_eq!(
        sarif["runs"][0]["tool"]["driver"]["name"], "bonsai-ninja",
        "[{lang}] sarif tool name should be bonsai-ninja"
    );
    let results = sarif["runs"][0]["results"]
        .as_array()
        .unwrap_or_else(|| panic!("[{lang}] sarif missing runs[0].results array"));
    for r in results {
        assert!(r.get("ruleId").is_some(), "[{lang}] sarif result missing ruleId");
        assert!(r.get("level").is_some(), "[{lang}] sarif result missing level");
        assert!(
            r["message"]["text"].as_str().is_some(),
            "[{lang}] sarif result missing message.text"
        );
        let loc = &r["locations"][0]["physicalLocation"];
        assert!(
            loc["artifactLocation"]["uri"].as_str().is_some(),
            "[{lang}] sarif result missing locations[0].physicalLocation.artifactLocation.uri"
        );
        assert!(
            loc["region"]["startLine"].as_u64().is_some(),
            "[{lang}] sarif result missing locations[0].physicalLocation.region.startLine"
        );
        let bonsai = &r["properties"]["bonsai"];
        let fid = bonsai["finding_id"]
            .as_str()
            .unwrap_or_else(|| panic!("[{lang}] sarif result missing properties.bonsai.finding_id"));
        assert!(
            fid.starts_with("S:") && fid.len() == 18,
            "[{lang}] malformed finding_id in sarif properties: {fid}"
        );
    }
    // Cross-format coherence drift guard: SARIF auto-includes
    // source-independent API misuse rows, so compare it to JSON with
    // `--include-pattern-only` rather than the default JSON taint-only
    // surface. This catches renderer divergence without weakening the
    // default JSON behavior.
    let Some((json_out, _, json_code)) = run(&[
        "security",
        ws,
        "taint-analysis",
        "--inferred-sources",
        "--include-pattern-only",
        "--format",
        "json",
    ]) else {
        return;
    };
    assert_eq!(
        json_code, 0,
        "[{lang}] security taint-analysis json ec={json_code}"
    );
    let json: serde_json::Value = serde_json::from_str(&json_out).unwrap();
    let json_rows = rows_of(&json);
    let json_ids: std::collections::BTreeSet<String> = json_rows
        .iter()
        .filter_map(|r| r.get("finding_id").and_then(|v| v.as_str()).map(String::from))
        .collect();
    let sarif_ids: std::collections::BTreeSet<String> = results
        .iter()
        .filter_map(|r| r["properties"]["bonsai"]["finding_id"].as_str().map(String::from))
        .collect();
    assert_eq!(
        json_ids, sarif_ids,
        "[{lang}] SARIF and JSON renderers cite different S: id sets — \
         renderers diverged. JSON ids: {json_ids:?}, SARIF ids: {sarif_ids:?}"
    );
}

/// Assert `tree --format json` runs and emits at least one root
/// node with the workspace summary populated. The shape — `roots`
/// + `summary` — is the canonical per-`docs/contributing/sdk.mdx` Browse facade
///   surface; this is the per-lang drift guard for the
///   `Project::browse().tree(...)` path.
fn check_tree_json_shape(ws: &str, lang: &str) {
    let Some((out, _, code)) = run(&["tree", ws, "--format", "json"]) else {
        return;
    };
    assert_eq!(code, 0, "[{lang}] tree ec={code}");
    let parsed: serde_json::Value = serde_json::from_str(&out).expect("tree json");
    let roots = parsed
        .get("roots")
        .and_then(|v| v.as_array())
        .unwrap_or_else(|| panic!("[{lang}] tree missing roots: {out}"));
    assert!(!roots.is_empty(), "[{lang}] tree roots empty");
    let summary = parsed
        .get("summary")
        .unwrap_or_else(|| panic!("[{lang}] tree missing summary"));
    let analysis_complete = parsed
        .get("analysis_complete")
        .and_then(|v| v.as_bool())
        .unwrap_or_else(|| panic!("[{lang}] tree missing analysis_complete bool: {out}"));
    let incomplete_reasons = parsed
        .get("analysis_incomplete_reasons")
        .and_then(|v| v.as_array())
        .unwrap_or_else(|| panic!("[{lang}] tree missing analysis_incomplete_reasons array: {out}"));
    if analysis_complete {
        assert!(
            incomplete_reasons.is_empty(),
            "[{lang}] complete tree view carried incomplete reasons: {out}"
        );
    } else {
        assert!(
            !incomplete_reasons.is_empty(),
            "[{lang}] incomplete tree view did not explain why: {out}"
        );
    }
    let total_files = summary.get("total_files").and_then(|v| v.as_u64()).unwrap_or(0);
    assert!(total_files > 0, "[{lang}] tree summary.total_files == 0");
    // Walk roots and assert every node carries a locator with a file path.
    fn walk(node: &serde_json::Value, lang: &str) {
        let loc = node
            .get("locator")
            .unwrap_or_else(|| panic!("[{lang}] tree node missing locator: {node}"));
        let file = loc.get("file").and_then(|v| v.as_str()).unwrap_or("");
        assert!(!file.is_empty(), "[{lang}] tree node locator.file empty");
        if let Some(children) = node.get("children").and_then(|v| v.as_array()) {
            for c in children {
                walk(c, lang);
            }
        }
    }
    for r in roots {
        walk(r, lang);
    }
}

/// Assert `read-file --format json` runs on a discovered fixture
/// file and emits the canonical SDK shape: `locator` with a file
/// path, `lines_total > 0`, `source` non-empty.
fn check_read_file_json_shape(ws: &str, lang: &str, handler: &str) {
    // Discover the file containing the handler decl via `defs --format json`.
    let Some((defs_out, _, code)) = run(&["defs", ws, "--name", handler, "--format", "json"]) else {
        return;
    };
    assert_eq!(code, 0, "[{lang}] defs --name {handler} ec={code}");
    let defs: serde_json::Value = serde_json::from_str(&defs_out).unwrap();
    let rows = defs.as_array().cloned().unwrap_or_default();
    let row = rows
        .iter()
        .find(|r| {
            r.get("kind").and_then(|v| v.as_str()) == Some("function")
                || r.get("kind").and_then(|v| v.as_str()) == Some("method")
        })
        .unwrap_or_else(|| panic!("[{lang}] defs --name {handler} found no function/method row"));
    let file = row
        .get("file")
        .and_then(|v| v.as_str())
        .unwrap_or_else(|| panic!("[{lang}] defs row missing file: {row}"))
        .to_string();
    let Some((out, stderr, code)) = run(&["read-file", ws, &file, "--format", "json"]) else {
        return;
    };
    assert_eq!(code, 0, "[{lang}] read-file ec={code}\nstderr: {stderr}");
    let parsed: serde_json::Value = serde_json::from_str(&out).expect("read-file json");
    let loc = parsed
        .get("locator")
        .unwrap_or_else(|| panic!("[{lang}] read-file missing locator: {out}"));
    let loc_file = loc.get("file").and_then(|v| v.as_str()).unwrap_or("");
    assert!(!loc_file.is_empty(), "[{lang}] read-file locator.file empty");
    let lines_total = parsed.get("lines_total").and_then(|v| v.as_u64()).unwrap_or(0);
    assert!(lines_total > 0, "[{lang}] read-file lines_total == 0");
    let source = parsed.get("source").and_then(|v| v.as_str()).unwrap_or("");
    assert!(!source.is_empty(), "[{lang}] read-file source empty");
    let analysis_complete = parsed
        .get("analysis_complete")
        .and_then(|v| v.as_bool())
        .unwrap_or_else(|| panic!("[{lang}] read-file missing analysis_complete bool: {out}"));
    let incomplete_reasons = parsed
        .get("analysis_incomplete_reasons")
        .and_then(|v| v.as_array())
        .unwrap_or_else(|| panic!("[{lang}] read-file missing analysis_incomplete_reasons array: {out}"));
    if analysis_complete {
        assert!(
            incomplete_reasons.is_empty(),
            "[{lang}] complete read-file view carried incomplete reasons: {out}"
        );
    } else {
        assert!(
            !incomplete_reasons.is_empty(),
            "[{lang}] incomplete read-file view did not explain why: {out}"
        );
    }
}

/// Assert `security sinks` surfaces the fixture's two pinned sink
/// families. This catches a command surface that still runs but silently
/// drops one of the language-specific security sink shapes.
fn check_security_sinks(ws: &str, lang: &str, cmdi_sink: &str, secondary_sink: &str) {
    let Some((out, _, code)) = run(&["security", ws, "sinks", "--format", "json"]) else {
        return;
    };
    assert_eq!(code, 0, "[{lang}] security sinks ec={code}");
    let parsed: serde_json::Value = serde_json::from_str(&out).unwrap();
    let rows = rows_of(&parsed);
    assert!(!rows.is_empty(), "[{lang}] security sinks empty");
    let joined = rows
        .iter()
        .filter_map(|row| row.get("text").and_then(|v| v.as_str()))
        .collect::<Vec<_>>()
        .join("\n");
    assert!(
        joined.contains(cmdi_sink),
        "[{lang}] security sinks did not surface expected command sink `{cmdi_sink}`; got:\n{joined}"
    );
    assert!(
        joined.contains(secondary_sink),
        "[{lang}] security sinks did not surface expected secondary sink `{secondary_sink}`; got:\n{joined}"
    );
    for row in rows {
        for field in ["rule_id", "text", "file", "line", "tag", "language"] {
            assert!(
                row.get(field).is_some(),
                "[{lang}] security sinks row missing `{field}`: {row}"
            );
        }
    }
}

