/// Assert `security source-analysis` does not merely render valid JSON:
/// non-empty languages must produce real source-lineage chains that
/// mention the fixture entrypoint.
fn check_security_source_analysis(ws: &str, lang: &str, expected_min: usize, handler: &str) {
    let Some((out, _, code)) = run(&["security", ws, "source-analysis", "--format", "json"]) else {
        return;
    };
    assert_eq!(code, 0, "[{lang}] security source-analysis ec={code}");
    let parsed: serde_json::Value = serde_json::from_str(&out).unwrap();
    let rows = rows_of(&parsed);
    if expected_min == 0 {
        assert!(
            rows.is_empty(),
            "[{lang}] security source-analysis reported unexpected source flows: {rows:?}"
        );
        return;
    }
    assert!(
        rows.len() >= expected_min,
        "[{lang}] security source-analysis = {}, want >= {expected_min}",
        rows.len()
    );
    // Solidity's micro source model is caller identity (`msg.sender`)
    // inside AuthService / modifiers rather than Gateway.handleRequest
    // HTTP-style entry data. Still require a concrete source-flow anchor,
    // but use the contract that owns the source.
    let expected_anchor = if lang == "solidity" {
        "AuthService"
    } else {
        handler
    };
    let mut mentions_handler = false;
    for row in &rows {
        assert!(
            row.get("source")
                .and_then(|source| source.get("rule_id"))
                .and_then(|v| v.as_str())
                .is_some_and(|rule| !rule.is_empty()),
            "[{lang}] source-analysis row missing source.rule_id: {row}"
        );
        let flow = row
            .get("flow")
            .unwrap_or_else(|| panic!("[{lang}] source-analysis row missing flow: {row}"));
        let chain = flow
            .get("chain")
            .and_then(|v| v.as_array())
            .unwrap_or_else(|| panic!("[{lang}] source-analysis flow missing chain: {row}"));
        assert!(!chain.is_empty(), "[{lang}] source-analysis chain empty: {row}");
        if chain
            .iter()
            .any(|item| item.as_str().is_some_and(|name| name.contains(expected_anchor)))
            || row
                .get("source")
                .and_then(|source| source.get("enclosing_fn"))
                .and_then(|v| v.as_str())
                .is_some_and(|name| name.contains(expected_anchor))
            || flow
                .get("functions")
                .and_then(|v| v.as_array())
                .is_some_and(|functions| {
                    functions.iter().any(|function| {
                        function
                            .get("owners")
                            .and_then(|v| v.as_array())
                            .is_some_and(|owners| {
                                owners.iter().any(|owner| {
                                    owner
                                        .get("name")
                                        .and_then(|v| v.as_str())
                                        .is_some_and(|name| name.contains(expected_anchor))
                                })
                            })
                    })
                })
        {
            mentions_handler = true;
        }
        let precision = flow.get("precision").and_then(|v| v.as_str()).unwrap_or("");
        assert!(
            matches!(precision, "exact" | "narrowed"),
            "[{lang}] source-analysis surfaced non-semantic precision `{precision}`: {row}"
        );
    }
    assert!(
        mentions_handler,
        "[{lang}] source-analysis never reached expected anchor `{expected_anchor}`"
    );
}

/// Assert `security source-analysis` stays semantic on the construct-heavy
/// mega_flow fixture, not just the tiny micro fixture.
fn check_mega_flow_source_analysis(ws: &str, lang: &str) {
    let Some((out, _, code)) = run(&["security", ws, "source-analysis", "--format", "json"]) else {
        return;
    };
    assert_eq!(code, 0, "[{lang}] mega_flow source-analysis ec={code}");
    let parsed: serde_json::Value = serde_json::from_str(&out).unwrap();
    let rows = rows_of(&parsed);
    assert!(
        !rows.is_empty(),
        "[{lang}] mega_flow source-analysis returned no source flows"
    );
    let mut has_multi_hop_semantic_flow = false;
    for row in &rows {
        let source = row
            .get("source")
            .unwrap_or_else(|| panic!("[{lang}] mega_flow source-analysis row missing source: {row}"));
        assert!(
            source
                .get("rule_id")
                .and_then(|v| v.as_str())
                .is_some_and(|rule| !rule.is_empty()),
            "[{lang}] mega_flow source-analysis source missing rule_id: {row}"
        );
        let flow = row
            .get("flow")
            .unwrap_or_else(|| panic!("[{lang}] mega_flow source-analysis row missing flow: {row}"));
        let precision = flow.get("precision").and_then(|v| v.as_str()).unwrap_or("");
        assert!(
            matches!(precision, "exact" | "narrowed"),
            "[{lang}] mega_flow source-analysis surfaced non-semantic precision `{precision}`: {row}"
        );
        let chain_len = flow.get("chain").and_then(|v| v.as_array()).map_or(0, Vec::len);
        if chain_len > 1 {
            has_multi_hop_semantic_flow = true;
        }
        assert!(
            row.get("analysis_complete").is_some(),
            "[{lang}] mega_flow source-analysis row missing analysis_complete: {row}"
        );
        assert!(
            row.get("analysis_incomplete_reasons").is_some(),
            "[{lang}] mega_flow source-analysis row missing incomplete reasons: {row}"
        );
    }
    if lang == "solidity" {
        assert!(
            rows.iter().any(|row| {
                row.get("source")
                    .and_then(|source| source.get("rule_id"))
                    .and_then(|v| v.as_str())
                    .is_some_and(|rule| rule == "solidity.msg.sender")
            }),
            "[{lang}] mega_flow source-analysis must keep exact caller-identity source rows: {rows:?}"
        );
    } else {
        assert!(
            has_multi_hop_semantic_flow,
            "[{lang}] mega_flow source-analysis did not render any multi-hop semantic flow: {rows:?}"
        );
    }
}

/// Assert `security deps` ties rulepack package keys back to real
/// evidence files, with exact-zero protection for languages whose
/// micro fixture has no package/dependency signals.
fn check_security_deps(ws: &str, lang: &str, expected_min: usize) {
    let Some((out, _, code)) = run(&["security", ws, "deps", "--format", "json"]) else {
        return;
    };
    assert_eq!(code, 0, "[{lang}] security deps ec={code}");
    let parsed: serde_json::Value = serde_json::from_str(&out).unwrap();
    let rows = rows_of(&parsed);
    if expected_min == 0 {
        assert!(
            rows.is_empty(),
            "[{lang}] security deps reported unexpected dependency evidence: {rows:?}"
        );
        return;
    }
    assert!(
        rows.len() >= expected_min,
        "[{lang}] security deps = {}, want >= {expected_min}",
        rows.len()
    );
    for row in rows {
        assert!(
            row.get("key")
                .and_then(|v| v.as_str())
                .is_some_and(|key| !key.is_empty()),
            "[{lang}] security deps row missing key: {row}"
        );
        assert!(
            row.get("rule_ids")
                .and_then(|v| v.as_array())
                .is_some_and(|rules| !rules.is_empty()),
            "[{lang}] security deps row missing rule_ids: {row}"
        );
        let key = row.get("key").and_then(|v| v.as_str()).unwrap_or("");
        let signals = row
            .get("signals")
            .and_then(|v| v.as_array())
            .cloned()
            .unwrap_or_default();
        assert!(
            signals
                .iter()
                .filter_map(|v| v.as_str())
                .any(|signal| dependency_signal_value(signal).is_some_and(|value| value == key)),
            "[{lang}] security deps row key `{key}` was not grounded by its own signal: {row}"
        );
        assert!(
            row.get("evidence_files")
                .and_then(|v| v.as_array())
                .is_some_and(|files| !files.is_empty()),
            "[{lang}] security deps row missing evidence_files: {row}"
        );
    }
}

fn dependency_signal_value(signal: &str) -> Option<&str> {
    [
        "frameworks:",
        "packages:",
        "imports:",
        "modules:",
        "manifests:",
        "lockfiles:",
    ]
    .iter()
    .find_map(|prefix| signal.strip_prefix(prefix))
}

