// =============================================================================
// Full-chain integration (mega_flow)
// =============================================================================
//
// Validates that the security taint-analysis pipeline produces AT LEAST ONE
// finding whose chain_display visits the expected chain of hops
// from the Flask handler all the way down to os.system.

/// Every expected hop that should appear in `chain_display` for a
/// full-chain finding from `handle_request` through the async
/// pipeline down to `CommandRunner.execute`.
const FULL_CHAIN_HOPS: &[&str] = &[
    "handle_request",
    "orchestrate",
    "stream_batch",
    "batch_expand",
    "normalize",
    "validate_payload",
    "persist",
    "perform",
    "execute",
];

#[test]
fn mega_flow_full_source_to_sink_chain_exists() {
    let Some(_) = bin_path() else { return };
    let w = ws("python", "mega_flow");
    let Some((out, _, code)) = run(&["security", &w, "taint-analysis", "--format", "json"]) else {
        return;
    };
    assert_eq!(code, 0, "mega_flow security taint-analysis ec={code}");
    let parsed: serde_json::Value = serde_json::from_str(&out).unwrap();
    let rows = rows_of(&parsed);
    assert!(!rows.is_empty(), "mega_flow: 0 findings (taint broken)");

    // At least one finding's chain must visit every hop.
    let any_full_chain = rows.iter().any(|r| {
        let chain = r
            .get("chain_display")
            .and_then(|c| c.as_array())
            .cloned()
            .unwrap_or_default();
        let chain_names: Vec<String> = chain
            .iter()
            .filter_map(|n| n.as_str().map(String::from))
            .collect();
        FULL_CHAIN_HOPS
            .iter()
            .all(|hop| chain_names.iter().any(|n| n.contains(hop)))
    });
    // This is the gold-standard test: one chain must visit every
    // hop. Accept a warning-only state when the engine's chain
    // enumeration heuristics exclude some hop (e.g. because it's
    // async) — but fail hard if the finding set is empty.
    if !any_full_chain {
        // Looser assertion: we need at least SOME finding whose
        // chain visits at least 5 of the 9 hops. Saves this test
        // from flaking on async-resolution edge cases while still
        // catching a regression where the chain collapses down to
        // just source + sink.
        let max_coverage = rows
            .iter()
            .map(|r| {
                let chain = r
                    .get("chain_display")
                    .and_then(|c| c.as_array())
                    .cloned()
                    .unwrap_or_default();
                let chain_names: Vec<String> = chain
                    .iter()
                    .filter_map(|n| n.as_str().map(String::from))
                    .collect();
                FULL_CHAIN_HOPS
                    .iter()
                    .filter(|hop| chain_names.iter().any(|n| n.contains(**hop)))
                    .count()
            })
            .max()
            .unwrap_or(0);
        assert!(
            max_coverage >= 5,
            "mega_flow: best chain covers only {max_coverage}/9 hops — \
             construct propagation regressed"
        );
    }
}

#[test]
fn mega_flow_dump_taint_threads_every_cross_function_hop() {
    let Some(_) = bin_path() else { return };
    let Some((out, _, code)) = mega_flow_dump_taint("handle_request") else {
        return;
    };
    assert_eq!(code, 0, "mega_flow dump-taint ec={code}");
    let parsed: serde_json::Value = serde_json::from_str(&out).unwrap();
    let records = parsed
        .get("records")
        .and_then(|r| r.as_array())
        .cloned()
        .unwrap_or_default();
    assert!(
        !records.is_empty(),
        "mega_flow dump-taint: zero propagation records"
    );
    // Every propagation record carries a taint_id stable across runs
    // and caller_name / callee_name populated from the resolver.
    for rec in &records {
        let id = rec.get("taint_id").and_then(|v| v.as_str()).unwrap_or("");
        assert!(id.starts_with("T:") && id.len() == 10, "taint_id malformed: {id}");
        assert!(
            rec.get("caller_name")
                .and_then(|v| v.as_str())
                .is_some_and(|s| !s.is_empty()),
            "taint record missing caller_name: {rec}"
        );
        assert!(
            rec.get("callee_name")
                .and_then(|v| v.as_str())
                .is_some_and(|s| !s.is_empty()),
            "taint record missing callee_name: {rec}"
        );
    }
    let mut edge_args: std::collections::HashMap<
        (String, String),
        std::collections::HashSet<(String, String)>,
    > = std::collections::HashMap::new();
    for rec in &records {
        let caller = rec
            .get("caller_name")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let callee = rec
            .get("callee_name")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let args = rec
            .get("tainted_args")
            .and_then(|v| v.as_array())
            .cloned()
            .unwrap_or_default();
        for arg in args {
            let value = arg
                .get("value_text")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string();
            let param = arg
                .get("param_name")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string();
            edge_args
                .entry((caller.clone(), callee.clone()))
                .or_default()
                .insert((value, param));
        }
    }
    let has_edge_arg = |caller: &str, callee: &str, value: Option<&str>, param: &str| {
        edge_args
            .get(&(caller.to_string(), callee.to_string()))
            .is_some_and(|args| {
                args.iter()
                    .any(|(v, p)| value.is_none_or(|expected| v == expected) && p == param)
            })
    };
    for (caller, callee, value, param) in [
        ("handle_request", "run_pipeline", Some("envelope"), "envelope"),
        ("run_pipeline", "orchestrate", Some("envelope"), "envelope"),
        ("orchestrate", "stream_batch", Some("envelope"), "envelope"),
        ("stream_batch", "batch_expand", Some("parts"), "parts"),
        ("stream_batch", "normalize", Some("expanded"), "item"),
        ("orchestrate", "validate_payload", Some("chunk"), "payload"),
        ("orchestrate", "persist", Some("repo"), "receiver"),
        ("persist", "perform", None, "cmd"),
        ("perform", "execute", Some("cmd"), "cmd"),
    ] {
        assert!(
            has_edge_arg(caller, callee, value, param),
            "mega_flow dump-taint missing tainted arg {caller}->{callee} value={value:?} param={param}; edge args: {edge_args:?}"
        );
    }
    let has_execute = records.iter().any(|rec| {
        rec.get("callee_name").and_then(|v| v.as_str()) == Some("execute")
            && rec
                .get("tainted_args")
                .and_then(|v| v.as_array())
                .is_some_and(|args| {
                    args.iter().any(|arg| {
                        arg.get("value_text").and_then(|v| v.as_str()) == Some("cmd")
                            && arg.get("param_name").and_then(|v| v.as_str()) == Some("cmd")
                    })
                })
    });
    assert!(
        has_execute,
        "mega_flow dump-taint must keep IDG-proven receiver/super flows into execute(cmd): {out}"
    );
}

