#[test]
fn mega_flow_call_edges_connect_consecutive_hops() {
    let Some(_) = bin_path() else { return };
    let w = ws("python", "mega_flow");
    let Some((out, _, _)) = run(&["export", &w]) else {
        return;
    };
    let parsed: serde_json::Value = serde_json::from_str(&out).unwrap();
    let tg = &parsed["taint_graph"];
    let fns = tg["functions"].as_array().unwrap();
    let edges = tg["call_edges"].as_array().unwrap();
    // Build func_id → name map.
    let id_to_name: std::collections::HashMap<u64, String> = fns
        .iter()
        .filter_map(|f| {
            let id = f.get("func_id").and_then(|v| v.as_u64())?;
            let n = f.get("name").and_then(|v| v.as_str())?;
            Some((id, n.to_string()))
        })
        .collect();
    // Resolve edges to names and build a callees map.
    let mut callees: std::collections::HashMap<String, Vec<String>> = std::collections::HashMap::new();
    for e in edges {
        let from = e.get("from").and_then(|v| v.as_u64()).unwrap_or(u64::MAX);
        let to = e.get("to").and_then(|v| v.as_u64()).unwrap_or(u64::MAX);
        if let (Some(f), Some(t)) = (id_to_name.get(&from), id_to_name.get(&to)) {
            callees.entry(f.clone()).or_default().push(t.clone());
        }
    }
    // Spot-check that specific chain edges exist.
    let expected_edges: &[(&str, &str)] = &[
        ("handle_request", "run_pipeline"),
        ("run_pipeline", "orchestrate"),
        ("orchestrate", "validate_payload"),
        ("persist", "perform"),
        ("perform", "execute"),
        ("execute", "os.system"),
    ];
    for (caller, callee) in expected_edges {
        let has_direct = callees
            .get(*caller)
            .map(|cs| cs.iter().any(|c| c.contains(callee)))
            .unwrap_or(false);
        // The call graph is FuncId-keyed so `os.system` (an external
        // call) won't be a resolvable edge — skip that case.
        if *callee == "os.system" {
            continue;
        }
        assert!(has_direct, "mega_flow call_edges missing `{caller} → {callee}`");
    }
}

