#[test]
fn mega_flow_propagations_span_every_hop() {
    let Some(_) = bin_path() else { return };
    let w = ws("python", "mega_flow");
    let Some((out, _, _)) = run(&["export", &w, "--full-propagations"]) else {
        return;
    };
    let parsed: serde_json::Value = serde_json::from_str(&out).unwrap();
    let tg = &parsed["taint_graph"];
    assert_eq!(
        tg["propagations_complete"], true,
        "mega_flow: --full-propagations must mark propagation records complete"
    );
    let props = tg["propagations"].as_array().unwrap();
    // Collect every (caller, callee) pair across propagations.
    // Export's `ExportTaintRecord` uses `caller` / `callee`
    // (not `caller_name` / `callee_name` like dump-taint's JSON).
    let mut edges: std::collections::HashSet<(String, String)> = std::collections::HashSet::new();
    for p in props {
        if let Some(recs) = p.get("records").and_then(|r| r.as_array()) {
            for r in recs {
                let caller = r.get("caller").and_then(|c| c.as_str()).unwrap_or("").to_string();
                let callee = r.get("callee").and_then(|c| c.as_str()).unwrap_or("").to_string();
                edges.insert((caller, callee));
            }
        }
    }
    // Export propagations are grouped by source-seeded records and do
    // not need to duplicate dump-taint's per-argument edge assertions.
    // Still require representative source, validation, and sink-tail
    // hops so this pass cannot silently collapse to an empty graph.
    let expected: &[(&str, &str)] = &[
        ("orchestrate", "validate_payload"),
        ("persist", "perform"),
        ("perform", "execute"),
        ("handle_request", "run_pipeline"),
        ("run_pipeline", "orchestrate"),
    ];
    let any_found = expected.iter().any(|(caller, callee)| {
        edges
            .iter()
            .any(|(c, d)| c.contains(caller) && d.contains(callee))
    });
    assert!(
        any_found,
        "mega_flow propagations didn't span ANY expected hop — \
         interproc pass broke entirely. Edges seen: {} total.",
        edges.len()
    );
}

