/// Every finding from `security taint-analysis` must have a well-formed
/// `finding_id`, `source`, `sink`, and (when resolved) `chain_display`.
#[test]
fn security_findings_have_well_formed_ids_and_chains() {
    let Some(_) = bin_path() else { return };
    // Use a language whose complex fixture produces many findings.
    let w = ws("python", "complex");
    let Some((out, _, _)) = run(&["security", &w, "taint-analysis", "--format", "json"]) else {
        return;
    };
    let parsed: serde_json::Value = serde_json::from_str(&out).unwrap();
    let rows = rows_of(&parsed);
    assert!(!rows.is_empty(), "python complex produced 0 findings");
    for r in rows {
        let id = r.get("finding_id").and_then(|v| v.as_str()).unwrap_or("");
        assert!(
            id.starts_with("S:") && id.len() == 18,
            "finding_id malformed: {id}"
        );
        let group = r.get("group_id").and_then(|g| g.as_str()).unwrap_or("");
        if !group.is_empty() {
            assert!(
                group.starts_with("G:") && group.len() == 18,
                "group_id malformed: {group}"
            );
        }
        let flow = r
            .get("representative_flow_id")
            .and_then(|f| f.as_str())
            .unwrap_or("");
        if !flow.is_empty() {
            assert!(
                flow.starts_with("F:") && flow.len() == 18,
                "representative_flow_id malformed: {flow}"
            );
        }
        // The sink location must have file + line.
        let sink = r.get("sink").unwrap();
        assert!(sink
            .get("file")
            .and_then(|f| f.as_str())
            .is_some_and(|s| !s.is_empty()));
        assert!(sink.get("line").and_then(|l| l.as_u64()).unwrap_or(0) > 0);
    }
}

