/// `imports` across every lang must include the `flows` column
/// populated for workspace-local imports (not just stdlib).
#[test]
fn imports_whole_module_resolve_to_flows() {
    let Some(_) = bin_path() else { return };
    // Pick langs where `micro` has at least one workspace-local
    // import. C/C++/Obj-C use `#include "x.h"`; Elixir uses `alias
    // MyApp.X`; Python uses `from .x import y`; Ruby uses
    // `require_relative`; Rust uses `use crate::x::y`. All must
    // produce at least one flow-id on an import row.
    for lang in [
        "c",
        "cpp",
        "objc",
        "elixir",
        "python",
        "ruby",
        "rust",
        "javascript",
        "typescript",
        "dart",
        "lua",
        "solidity",
        "perl",
        "php",
    ] {
        let w = ws(lang, "micro");
        let Some((out, _, _)) = run(&["imports", &w]) else {
            return;
        };
        assert!(
            out.contains("F:"),
            "[{lang}] imports has no F: flow id — whole-module resolution regressed"
        );
    }
}

