/// Pagination cursor round-trip: page 1's `next_cursor` must match
/// page 2's `cursor`.
#[test]
fn pagination_cursor_advances_correctly() {
    let Some(_) = bin_path() else { return };
    let w = ws("python", "complex");
    let Some((out1, _, _)) = run(&["defs", &w, "--context", "4k", "--format", "json"]) else {
        return;
    };
    let p1: serde_json::Value = serde_json::from_str(&out1).unwrap();
    let next_cursor = match p1
        .get("page")
        .and_then(|p| p.get("next_cursor"))
        .and_then(|c| c.as_str())
    {
        Some(c) => c.to_string(),
        None => return, // single-page result
    };
    let Some((out2, _, _)) = run(&[
        "defs",
        &w,
        "--context",
        "4k",
        "--page",
        &next_cursor,
        "--format",
        "json",
    ]) else {
        return;
    };
    let p2: serde_json::Value = serde_json::from_str(&out2).unwrap();
    let cursor2 = p2
        .get("page")
        .and_then(|p| p.get("cursor"))
        .and_then(|c| c.as_str())
        .unwrap_or("");
    assert_eq!(
        cursor2, next_cursor,
        "page 2 cursor didn't match page 1's next_cursor"
    );
}

/// `--compact` on `inspect` drops source bodies but keeps flow headers
/// and step lists.
#[test]
fn inspect_compact_keeps_headers_drops_bodies() {
    let Some(_) = bin_path() else { return };
    let w = ws("python", "micro");
    let Some((compact, _, _)) = run(&[
        "inspect",
        &w,
        "--query",
        "handle_request",
        "--graph-flow",
        "--compact",
    ]) else {
        return;
    };
    let Some((full, _, _)) = run(&["inspect", &w, "--query", "handle_request", "--graph-flow"]) else {
        return;
    };
    assert!(compact.contains("FLOW 1"), "compact mode dropped FLOW header");
    // Compact mode should never include the inlined `def handle_request`
    // function body.
    assert!(
        full.len() > compact.len(),
        "compact output not smaller than full: {} vs {}",
        compact.len(),
        full.len()
    );
}

